use spore_core::{creature_skin_edge_commit_v1::commit,native_sse::Policy};use std::io::Write;
fn main(){let mut bytes=Vec::new();for case in 0..3{let mut records=[[0,0,77,0,0,0]];let mut positions=[[1.,2.,3.]];let mut counts=[[5,if case==2{u32::MAX}else{7}]];let mut slots=vec![[0;3];0x8000];let mut len=1;let point=match case{0=>[0.5,-1.,1.],1=>[-1.,-2.,-3.],_=>[0.,0.,0.]};let idx=commit(&mut records,0,9,&mut positions,&mut counts,&mut len,&mut slots,1,[3,4],point,Policy::Mxcsr1f80).unwrap();for x in [idx,positions[0][0].to_bits(),positions[0][1].to_bits(),positions[0][2].to_bits(),counts[0][0],counts[0][1]]{bytes.extend_from_slice(&x.to_le_bytes());}}std::io::stdout().write_all(&bytes).unwrap();}
